p='public/index.html'; h=open(p,encoding='utf8').read()
def rep(old,new):
    global h
    assert old in h, old[:60]; h=h.replace(old,new,1)
rep("  { g: 'البحار والمياه والجو', ic: '🌊' },\n];", "  { g: 'البحار والمياه والجو', ic: '🌊' },\n  { g: 'الحيوان', ic: '🕷️' },\n];")
rep("{ g: 0, t: 'النحل والعسل',", "{ g: 4, t: 'النحل والعسل',")
new_items = r'''  { g: 0, t: 'تقليب أهل الكهف', note: 'يشير بعضهم إلى أن تقليب النائم مدةً طويلة يقي من تقرّحات الفراش وتلف الأنسجة، ويرون في قوله «نقلّبهم» حفظاً لأجسادهم. والمعنى الظاهر عند المفسرين بيان حفظ الله لهم في نومهم الطويل.', keys: ['18:18'] },
  { g: 0, t: 'قلب واحد في الجوف', note: 'المعنى الظاهر عند المفسرين أن الإنسان لا يجتمع في قلبه ولاءان متعارضان (ردّاً على عادات جاهلية). ويشير بعضهم إلى أن للإنسان قلباً واحداً، ويرى آخرون أن الآية مجاز ولا تدخل في الإعجاز العلمي.', keys: ['33:4'] },
  { g: 1, t: 'الخُنَّس الجواري الكُنَّس', note: 'يرى بعض المعاصرين في الخنّس (التي تختفي) الجواري (التي تجري) الكنّس (التي تكنس وتبتلع ما حولها) إشارة إلى الثقوب السوداء. أما المفسرون القدامى فحملوها على الكواكب أو النجوم التي تختفي نهاراً وتجري وتغيب، وقيل غير ذلك؛ فهو اجتهاد محتمل لا قطعي.', keys: ['81:15', '81:16'] },
  { g: 1, t: 'الشمس تجري لمستقرّ لها', note: 'يرى بعضهم أن للشمس حركة في الفضاء نحو وجهة معينة وفي مدارها حول مركز المجرة. وفسّرها المفسرون القدامى بأن مستقرها نهاية أجلها أو موضع انتهاء سيرها يوم القيامة.', keys: ['36:38'] },
  { g: 4, t: 'بيت العنكبوت', note: 'يتأمل بعضهم في «اتخذت» بصيغة المؤنث إشارةً إلى أن الأنثى هي التي تنسج البيت، وفي هشاشة بيت العنكبوت كمسكن وفي علاقات أفراده. والمعنى الظاهر مَثَلٌ لضعف من اتخذ من دون الله أولياء.', keys: ['29:41'] },
'''
rep("  { g: 1, t: 'اتساع السماء',", new_items + "  { g: 1, t: 'اتساع السماء',")
